/* ایستگاه‌های آزمونک: بعد از کدام منزل (از صفر) و چند پرسش برای هر سطح */
const QUIZ_AT=[
 {after:1,n:{a:4,b:5,c:6,d:6}},
 {after:3,n:{a:5,b:6,c:7,d:8}},
 {after:6,n:{a:5,b:6,c:7,d:8}},
 {after:9,n:{a:6,b:7,c:8,d:8}},
 {after:11,n:{a:6,b:8,c:10,d:10}}];

/* انتخاب پرسش‌ها: بیشتر از سرزمین فعلی، دست‌کم یکی از قبل (اگر باشد)، بی‌تکرار، به هم ریخته */
function quizPick(level,stopIndex,rng){
  rng=rng||Math.random;
  const T=QTERMS[level]||QTERMS.c,qa=QUIZ_AT.find(x=>x.after===stopIndex),n=qa?(qa.n[level]||qa.n.c):6;
  const sh=a=>{for(let i=a.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
  const land0=stopIndex<4?0:stopIndex<10?4:10;
  const mk=(from,to)=>{const ts=[];for(let i=from;i<=to&&i<T.length;i++)T[i].forEach(t=>{if(!ts.includes(t))ts.push(t);});
    return sh(ts.map(t=>sh(QBANK.filter(q=>q.term===t&&q.lv.includes(level)))).filter(p=>p.length));};
  const cur=mk(land0,stopIndex),old=mk(0,land0-1),out=[],seen=new Set();
  const take=(pools,k)=>{let got=0,moved=true;while(got<k&&moved){moved=false;for(const p of pools){if(got>=k)break;while(p.length){const q=p.pop();if(!seen.has(q.id)){seen.add(q.id);out.push(q);got++;moved=true;break;}}}}};
  const kOld=old.length?Math.max(1,Math.round(n*.3)):0;
  take(cur,n-kOld);take(old,n-out.length);take(cur,n-out.length);
  return sh(out).map(q=>Object.assign({},q,{opts:q.opts.slice()}));
}
